import type { D1Migration } from "cloudflare:test";

// vitest-pool-workers 0.18 types `env` as `Cloudflare.Env`, so test-only
// bindings are declared by augmenting that namespace rather than `ProvidedEnv`.
// DB and ASSETS come from worker-configuration.d.ts (generated by `wrangler types`);
// these two exist only when running under vitest.
declare global {
  namespace Cloudflare {
    interface Env {
      TEST_MIGRATIONS: D1Migration[];
      SESSION_SECRET: string;
    }
  }
}
